/*
 * A208518  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A208519; see the Formula section.
 * https://oeis.org/A208518
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the n-th element of the triangle of coefficients * of
 *            the polynomials u(n,x) generated by * u(1,x) = 1, v(1,x) = 1 *
 *            u(n,x) = u(n-1,x) + x*v(n-1,x) * v(n,x) = x*u(n-1,x) +
 *            (x+1)*v(n-1,x) + 1 * The triangle is read row‑wise (row r has r
 *            coefficients); * a(n) is the coefficient of the n-th...
 * Range:     u8 n <= 39, u16 n <= 63, u32 n <= 63, u64 n <= 63, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>

/* Return the n-th term of the sequence (n>=1). */
seq_t a(idx_t n) {
    if (n == 0) return 0; /* offset is 1, never used */

    /* Find the row r such that r*(r+1)/2 >= n */
    idx_t r = 0;
    idx_t sum = 0;
    while (sum < n) {
        ++r;
        sum += r;
    }
    /* Number of terms before this row */
    idx_t prev_total = (r - 1) * r / 2;
    /* 0‑based index inside the row */
    idx_t offset = n - prev_total - 1;
    size_t n_rows = (size_t)r;          /* number of coefficients in the last row */

    /* Special case: first row */
    if (r == 1) {
        return (seq_t)1;
    }

    /* Allocate space for up to r coefficients for u and v */
    size_t max_len = n_rows;
    seq_t *u_prev = (seq_t *)calloc(max_len, sizeof(seq_t));
    seq_t *v_prev = (seq_t *)calloc(max_len, sizeof(seq_t));
    seq_t *u_cur  = (seq_t *)calloc(max_len, sizeof(seq_t));
    seq_t *v_cur  = (seq_t *)calloc(max_len, sizeof(seq_t));

    /* Initial row (r = 1) */
    u_prev[0] = 1;
    v_prev[0] = 1;
    size_t prev_len = 1;

    /* Build rows 2..r */
    for (idx_t row = 2; row <= r; ++row) {
        size_t new_len = prev_len + 1;

        /* Compute u_cur and v_cur */
        for (size_t i = 0; i < new_len; ++i) {
            seq_t u_part = (i < prev_len) ? u_prev[i] : 0;
            seq_t v_part = (i > 0)        ? v_prev[i - 1] : 0;
            u_cur[i] = u_part + v_part;

            seq_t uprev_i   = (i > 0)      ? u_prev[i - 1] : 0;
            seq_t vprev_i   = (i < prev_len) ? v_prev[i] : 0;
            seq_t vprev_im1 = (i > 0)      ? v_prev[i - 1] : 0;
            seq_t const_one = (i == 0)    ? (seq_t)1 : 0;
            v_cur[i] = uprev_i + vprev_i + vprev_im1 + const_one;
        }

        /* Prepare for next iteration */
        seq_t *tmp = u_prev; u_prev = u_cur; u_cur = tmp;
        tmp = v_prev;       v_prev = v_cur; v_cur = tmp;
        prev_len = new_len;
    }

    /* Result is the coefficient at position 'offset' in u_prev */
    seq_t result = u_prev[(size_t)offset];

    /* Free allocated memory */
    free(u_prev);
    free(v_prev);
    free(u_cur);
    free(v_cur);

    return result;
}
